 (function () {
   'use strict';

   const form     = document.getElementById('contact-form');
   const statusEl = document.getElementById('form-status');

   /** Show an error for one field. */
   function setError(inputEl, errorEl, message) {
     inputEl.setAttribute('aria-invalid', 'true');
     errorEl.textContent = message;
     errorEl.classList.add('visible');
   }

   /** Clear the error for one field. */
   function clearError(inputEl, errorEl) {
     inputEl.removeAttribute('aria-invalid');
     errorEl.textContent = '';
     errorEl.classList.remove('visible');
   }

   /** Clear the global status region. */
   function clearStatus() {
     statusEl.textContent = '';
     statusEl.className = 'form-status';
   }

   /** Validate all fields; returns array of invalid inputs (in DOM order). */
   function validateAll() {
     const invalid = [];

     const name      = document.getElementById('full-name');
     const nameErr   = document.getElementById('full-name-error');
     const email     = document.getElementById('email');
     const emailErr  = document.getElementById('email-error');
     const phone     = document.getElementById('phone');
     const phoneErr  = document.getElementById('phone-error');

