       setError(email, emailErr, 'Error: Email address is required.');
       invalid.push(email);
     } else if (!emailPattern.test(email.value.trim())) {
       setError(email, emailErr, 'Error: Enter a valid email address, e.g. name@example.com.');
       invalid.push(email);
     } else {
       clearError(email, emailErr);
     }

     // Phone — optional, but if provided must look like digits/spaces/dashes/parens
     const phoneVal = phone.value.trim();
     if (phoneVal && !/^[+\d][\d\s\-().]{6,19}$/.test(phoneVal)) {
       setError(phone, phoneErr, 'Error: Enter a valid phone number, e.g. +1 (555) 000-1234.');
       invalid.push(phone);
     } else {
       clearError(phone, phoneErr);
     }

