       const noun = invalid.length === 1 ? 'error' : 'errors';
       statusEl.className = 'form-status error';
       statusEl.textContent =
         `${invalid.length} ${noun} found. Please correct the highlighted field${invalid.length > 1 ? 's' : ''} below.`;
