     statusEl.className = 'form-status success';
     statusEl.textContent = 'Your message has been sent. We'll be in touch soon.';
     form.reset();
   });

   // Live clear-on-fix: remove error as soon as the user corrects the field
   form.addEventListener('input', function (e) {
     const input = e.target;
